<?php
namespace App\Http\Controllers\Api;
use App\Http\Requests\EnterpriseRequest; use App\Http\Requests\MasterIndexRequest; use App\Http\Resources\HolidayResource; use App\Models\Holiday; use App\Repositories\EnterpriseRepository; use App\Services\EnterpriseService;
class HolidayController extends BaseApiController { private EnterpriseService $service; public function __construct(){ $this->service=new EnterpriseService(new EnterpriseRepository(new Holiday)); } public function index(MasterIndexRequest $r){return $this->respondWithResource(HolidayResource::collection($this->service->paginate($r->validated())),'Holidays retrieved successfully.');} public function store(EnterpriseRequest $r){return $this->respondSuccess(new HolidayResource($this->service->create($r->validated())),'Holiday created successfully.',201);} public function show(Holiday $holiday){return $this->respondSuccess(new HolidayResource($holiday));} public function update(EnterpriseRequest $r,Holiday $holiday){return $this->respondSuccess(new HolidayResource($this->service->update($holiday,$r->validated())),'Holiday updated successfully.');} public function destroy(Holiday $holiday){$this->service->delete($holiday);return $this->respondSuccess(null,'Holiday deleted successfully.');} }
